// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------

/// <summary>Stores research notes collected by the agent.</summary>
sealed class Notebook
{
    private readonly List<string> _notes = [];
    public void Add(string note) => _notes.Add(note);
    public IReadOnlyList<string> Notes => _notes;
}

/// <summary>Tools exposed to the research agent.</summary>
sealed class ResearchTools(Notebook notebook)
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information on a query. Returns a list of results with titles, snippets, and URLs.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        // Use DuckDuckGo Instant Answer API (no key required)
        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://duckduckgo.com/html/?q={encoded}";

        try
        {
            var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.Add("Accept", "text/html");
            var response = await Http.SendAsync(request);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync();
            var results = ParseSearchResults(html, maxResults: 5);

            if (results.Count == 0)
                return "No results found for the query.";

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for \"{query}\":");
            foreach (var (title, snippet, link) in results)
            {
                sb.AppendLine($"- **{title}**");
                sb.AppendLine($"  {snippet}");
                sb.AppendLine($"  URL: {link}");
            }
            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note. Use this to record important facts, data points, or insights found during research.")]
    public string TakeNote(
        [Description("The note content to save")] string note,
        [Description("Source URL or reference for this note")] string source)
    {
        notebook.Add($"[{source}] {note}");
        return $"Note saved. You now have {notebook.Notes.Count} note(s).";
    }

    [Description("Review all notes taken so far. Use this before writing the final summary.")]
    public string ReviewNotes()
    {
        if (notebook.Notes.Count == 0)
            return "No notes taken yet. Search for information first.";

        var sb = new StringBuilder();
        sb.AppendLine($"=== {notebook.Notes.Count} Research Notes ===");
        for (var i = 0; i < notebook.Notes.Count; i++)
            sb.AppendLine($"{i + 1}. {notebook.Notes[i]}");
        return sb.ToString();
    }

    /// <summary>Basic HTML scraping of DuckDuckGo result snippets.</summary>
    private static List<(string Title, string Snippet, string Url)> ParseSearchResults(
        string html, int maxResults)
    {
        var results = new List<(string, string, string)>();
        var span = html.AsSpan();

        const string resultMarker = "class=\"result__a\"";
        const string snippetMarker = "class=\"result__snippet\"";

        var pos = 0;
        while (results.Count < maxResults && pos < html.Length)
        {
            var markerIdx = html.IndexOf(resultMarker, pos, StringComparison.Ordinal);
            if (markerIdx < 0) break;

            var href = ExtractAttribute(html, markerIdx, "href");
            var title = ExtractTagContent(html, markerIdx);

            var snippetIdx = html.IndexOf(snippetMarker, markerIdx, StringComparison.Ordinal);
            var snippet = snippetIdx >= 0 ? ExtractTagContent(html, snippetIdx) : "";

            if (!string.IsNullOrEmpty(title))
            {
                var url = CleanDdgUrl(href);
                results.Add((
                    WebUtility.HtmlDecode(title).Trim(),
                    WebUtility.HtmlDecode(snippet).Trim(),
                    url));
            }

            pos = markerIdx + resultMarker.Length;
        }

        return results;
    }

    private static string ExtractAttribute(string html, int startFrom, string attr)
    {
        var attrPattern = $"{attr}=\"";
        var idx = html.IndexOf(attrPattern, startFrom, StringComparison.Ordinal);
        if (idx < 0) return "";
        var start = idx + attrPattern.Length;
        var end = html.IndexOf('"', start);
        return end > start ? html[start..end] : "";
    }

    private static string ExtractTagContent(string html, int startFrom)
    {
        var gt = html.IndexOf('>', startFrom);
        if (gt < 0) return "";
        var start = gt + 1;
        var end = html.IndexOf('<', start);
        if (end < 0) return "";
        // Grab text across inner tags too
        var closeTag = html.IndexOf("</", start, StringComparison.Ordinal);
        if (closeTag < 0) return html[start..end].Trim();

        var sb = new StringBuilder();
        var p = start;
        while (p < closeTag)
        {
            var lt = html.IndexOf('<', p);
            if (lt < 0 || lt >= closeTag) { sb.Append(html.AsSpan(p, closeTag - p)); break; }
            sb.Append(html.AsSpan(p, lt - p));
            var nextGt = html.IndexOf('>', lt);
            if (nextGt < 0) break;
            p = nextGt + 1;
        }
        return sb.ToString().Trim();
    }

    private static string CleanDdgUrl(string href)
    {
        // DuckDuckGo wraps URLs in a redirect; extract the actual URL
        const string prefix = "//duckduckgo.com/l/?uddg=";
        if (href.Contains(prefix))
        {
            var start = href.IndexOf(prefix) + prefix.Length;
            var end = href.IndexOf('&', start);
            var encoded = end > 0 ? href[start..end] : href[start..];
            return WebUtility.UrlDecode(encoded);
        }
        return href.StartsWith("//") ? "https:" + href : href;
    }
}

